/**
 * Corpus-driven ball commentary.
 *
 * The model is generated by packages/ratings/src/analysis/commentary-build.py from real ball-by-ball
 * commentary (see docs/COMMENTARY.md). It holds
 *   - templates per outcome class (dot, 1, 2, 3, 4, 6, wide, noball, legbye, W:<dismissal kind>), with the
 *     player names already replaced by {batter} {bowler} {fielder} {nonstriker} and pronouns by {he} {him} {his}
 *     {himself}; every template carries the tags of the real ball it came from (shot, line, length, field zone,
 *     control, bowler kind, phase, pressure, batter hand);
 *   - the joint distribution of those tags given outcome, bowler kind and batter hand.
 *
 * The simulator does not model shot/line/length, so for each ball we SAMPLE them from the joint distribution
 * (consistent with the outcome by construction) and pick a template whose tags are closest. Selection uses only
 * the RNG it is handed, never touches the simulation's own stream, and skips lines already used in the match.
 *
 * Nothing here is bundled: the app fetches the JSON lazily (loadCommentaryModel). Until a model is set the
 * engine keeps using the hand-written lines in commentary.ts.
 */

import type { RNG } from "./rng.js";

export interface CommentaryModelData {
  v: number;
  dict: { shot: (string | null)[]; line: (string | null)[]; len: (string | null)[]; bk: string[]; hand: string[]; ph: string[]; pr: string[] };
  /** "<class>|<bowler kind idx>|<hand idx>" -> [shot, line, len, zone, ctl, weight][] */
  joint: Record<string, number[][]>;
  /** class -> parallel arrays of template text and packed tags */
  lines: Record<string, { t: string[]; g: number[] }>;
  corpus?: { balls: number; balls_with_text: number; templates: number };
}

export type ModelOutcome = "dot" | "1" | "2" | "3" | "4" | "6" | "wide" | "noball" | "legbye" | "wicket";

export interface ModelBall {
  outcome: string;
  wicketType?: string;
  bowlingStyle?: string;
  battingHand?: string;
  over: number;
  ball: number;
  score: number;
  wickets: number;
  isSecondInnings: boolean;
  target?: number;
  gender?: "male" | "female";
  batterName: string;
  bowlerName: string;
  fielderName?: string;
  nonStrikerName?: string;
  /** A run out that took the non-striker: picks the "W:run_out_ns" templates (the partner is out, the striker played the shot) */
  outNonStriker?: boolean;
  /** The fielder is a substitute: the line says "substitute X" the first time the fielder is named */
  substitute?: boolean;
  /** Only templates whose text passes (e.g. a wide down the leg side) */
  textFilter?: (templateText: string) => boolean;
}

/** What was drawn for a ball (exposed for tests and tooling). */
export interface ModelPick {
  text: string;
  /** "<class>:<template index>", used to avoid repeating a line inside one match */
  key: string;
  tags: { shot: string | null; line: string | null; length: string | null; zone: number; control: number };
}

interface ClassIndex {
  t: string[];
  g: number[];
  slots: number[]; // bit mask of slots a template needs: 1 batter, 2 bowler, 4 fielder, 8 nonstriker
  byShot: Map<number, number[]>;
}

let MODEL: CommentaryModelData | null = null;
let INDEX: Record<string, ClassIndex> = {};

/** Below this many unused lines for a ball the picker steps aside (the built-in lines answer instead). */
export const MIN_UNUSED = 4;

const SLOT_BITS: Record<string, number> = { batter: 1, bowler: 2, fielder: 4, nonstriker: 8 };

export function setCommentaryModel(data: CommentaryModelData | null): void {
  MODEL = data;
  INDEX = {};
  if (!data) return;
  for (const [cls, { t, g }] of Object.entries(data.lines)) {
    const slots = t.map((text) => {
      let m = 0;
      const re = /\{(batter|bowler|fielder|nonstriker)\}/g;
      let x: RegExpExecArray | null;
      while ((x = re.exec(text))) m |= SLOT_BITS[x[1]];
      return m;
    });
    const byShot = new Map<number, number[]>();
    g.forEach((p, i) => {
      const shot = p & 63;
      const arr = byShot.get(shot);
      if (arr) arr.push(i);
      else byShot.set(shot, [i]);
    });
    INDEX[cls] = { t, g, slots, byShot };
  }
}

export function hasCommentaryModel(): boolean {
  return MODEL !== null;
}

export function getCommentaryModel(): CommentaryModelData | null {
  return MODEL;
}

/** Fetch + install the model (browser or Node 18+). Resolves false (and keeps the fallback) on any failure. */
export async function loadCommentaryModel(url = "/data/commentary-model.json"): Promise<boolean> {
  try {
    const res = await fetch(url);
    if (!res.ok) return false;
    setCommentaryModel((await res.json()) as CommentaryModelData);
    return true;
  } catch {
    return false;
  }
}

/* ───────────────────────── small helpers ───────────────────────── */

function hash32(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

/** bowler kind index into dict.bk: 0 unknown, 1 fast, 2 medium, 3 offspin, 4 orthodox, 5 legspin */
export function bowlerKindIndex(style?: string): number {
  switch (style) {
    case "right-arm-fast": case "left-arm-fast": case "right-arm-fast-medium": case "left-arm-fast-medium": return 1;
    case "right-arm-medium-fast": case "left-arm-medium-fast": case "right-arm-medium": case "left-arm-medium":
    case "right-arm-slow": case "left-arm-slow": return 2;
    case "off-spin": return 3;
    case "left-arm-orthodox": return 4;
    case "leg-spin": case "left-arm-wrist-spin": return 5;
    default: return 0;
  }
}

function handIndex(h?: string): number {
  return h === "right" ? 1 : h === "left" ? 2 : 0;
}

const COMMON_SURNAMES = new Set(["singh", "kumar", "khan", "yadav", "patel", "ali", "ahmed", "ahmad", "sharma", "kaur", "devi", "reddy", "jr", "mohammad", "muhammad"]);

/** How a commentator would say the name: surname, or first name for very common surnames ("Rohit", "Hardik"). */
export function commentaryShortName(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length <= 1) return parts[0] ?? name;
  const last = parts[parts.length - 1];
  const first = parts[0];
  if (COMMON_SURNAMES.has(last.toLowerCase()) && first.length > 2 && !/^[A-Z]\.?$/.test(first)) return first;
  return last;
}

function sampleWeighted<T>(items: T[], weights: number[], rng: RNG): T {
  let tot = 0;
  for (const w of weights) tot += w;
  let r = rng() * tot;
  for (let i = 0; i < items.length; i++) {
    r -= weights[i];
    if (r <= 0) return items[i];
  }
  return items[items.length - 1];
}

function pressureOf(b: ModelBall, phaseIdx: number): number {
  const legal = b.over * 6 + Math.max(0, b.ball - 1);
  if (b.isSecondInnings && b.target && legal < 120) {
    const rrr = ((b.target - b.score) * 6) / (120 - legal);
    if (rrr >= 12 || (rrr >= 9.5 && b.wickets >= 5) || b.wickets >= 8) return 2;
    if (rrr <= 7.5 && b.wickets <= 3) return 0;
    return 1;
  }
  if (b.wickets >= 6 && phaseIdx !== 2) return 2;
  if (phaseIdx === 1 && b.wickets <= 1) return 0;
  return 1;
}

function classKey(b: ModelBall): string | null {
  if (b.outcome === "wicket") {
    const k = b.wicketType ?? "";
    if (k === "run_out" && b.outNonStriker) return "W:run_out_ns";
    return ["bowled", "caught", "lbw", "run_out", "stumped", "caught_and_bowled"].includes(k) ? `W:${k}` : null;
  }
  return ["dot", "1", "2", "3", "4", "6", "wide", "noball", "legbye"].includes(b.outcome) ? b.outcome : null;
}

function sampleTags(cls: string, bk: number, hand: number, rng: RNG): number[] | null {
  if (!MODEL) return null;
  const j = MODEL.joint;
  // thin classes borrow the tags of their parent (non-striker run outs from run outs, caught and bowled from caught)
  const parent = cls === "W:run_out_ns" ? "W:run_out" : cls === "W:caught_and_bowled" ? "W:caught" : cls;
  const cell = j[`${cls}|${bk}|${hand}`] ?? j[`${cls}|${bk}|0`] ?? j[`${cls}|0|${hand}`] ?? j[`${cls}|0|0`]
    ?? j[`${parent}|${bk}|${hand}`] ?? j[`${parent}|${bk}|0`] ?? j[`${parent}|0|${hand}`] ?? j[`${parent}|0|0`];
  if (!cell || cell.length === 0) return null;
  return sampleWeighted(cell, cell.map((c) => c[5]), rng);
}

function scoreTemplate(g: number, shot: number, line: number, len: number, zone: number, ctl: number, bk: number, ph: number, pr: number, hand: number): number {
  const tShot = g & 63, tLine = (g >> 6) & 15, tLen = (g >> 10) & 15, tZone = (g >> 14) & 15, tCtl = (g >> 18) & 3, tBk = (g >> 20) & 7;
  const tPh = (g >> 23) & 3, tPr = (g >> 25) & 3, tHand = (g >> 27) & 3;
  let s = 0;
  if (tShot && shot) s += tShot === shot ? 4 : -3;
  if (tLen && len) s += tLen === len ? 2 : -1.5;
  if (tLine && line) s += tLine === line ? 2 : -1;
  if (tZone && zone) s += tZone === zone ? 1.5 : -0.5;
  if (tCtl !== 3 && ctl !== 3) s += tCtl === ctl ? 1 : -0.5;
  if (tBk && bk) {
    const spinT = tBk >= 3, spinB = bk >= 3;
    if (tBk === bk) s += 1.5;
    else if (spinT !== spinB) s -= 4;
    else s -= spinT ? 2 : 0.5;
  }
  if (tPh === ph) s += 0.5;
  if (tPr === pr) s += 1;
  else if (Math.abs(tPr - pr) === 2) s -= 0.5;
  if (tHand && hand && tHand === hand) s += 0.5;
  return s;
}

function fill(text: string, b: ModelBall): string {
  const female = b.gender === "female";
  const names: Record<string, string> = {
    batter: commentaryShortName(b.batterName),
    bowler: commentaryShortName(b.bowlerName),
    fielder: b.fielderName ? commentaryShortName(b.fielderName) : "",
    nonstriker: b.nonStrikerName ? commentaryShortName(b.nonStrikerName) : "",
    he: female ? "she" : "he", him: female ? "her" : "him", his: female ? "her" : "his", himself: female ? "herself" : "himself",
  };
  let subPending = !!b.substitute && !!b.fielderName;
  const filled = text.replace(/\{(\w+)\}/g, (m, k: string) => {
    if (k === "fielder" && subPending) { subPending = false; return `substitute ${names.fielder}`; }
    return names[k] ?? m;
  });
  // pronouns (and "substitute") that open a sentence need a capital ("{he} swivels" -> "He swivels")
  return filled.replace(/(^|[.!?]["']?\s+)(she|he|her|his|him|herself|himself|substitute)\b/g, (_m, p: string, w: string) => p + w[0].toUpperCase() + w.slice(1));
}

/**
 * Draw a corpus line for this ball, or null when there is no model / no usable template
 * (the caller then falls back to the built-in lines).
 */
export function pickModelCommentary(b: ModelBall, rng: RNG, used?: Readonly<Record<string, unknown>>): ModelPick | null {
  if (!MODEL) return null;
  const cls = classKey(b);
  if (!cls) return null;
  const ix = INDEX[cls];
  if (!ix || ix.t.length === 0) return null;

  const bk = bowlerKindIndex(b.bowlingStyle);
  const hand = handIndex(b.battingHand);
  const phIdx = b.over < 6 ? 0 : b.over < 15 ? 1 : 2;
  const pr = pressureOf(b, phIdx);
  const tags = sampleTags(cls, bk, hand, rng);
  const [shot, line, len, zone, ctl] = tags ?? [0, 0, 0, 0, 3];

  let have = 1 | 2;
  if (b.fielderName) have |= 4;
  if (b.nonStrikerName) have |= 8;

  let pool = ix.byShot.get(shot);
  if (!pool || pool.length < 25) pool = undefined;
  const take = (cands: number[] | undefined, seen: Readonly<Record<string, unknown>> | undefined) => {
    const scored: { i: number; s: number }[] = [];
    const n = cands ? cands.length : ix.t.length;
    for (let k = 0; k < n; k++) {
      const i = cands ? cands[k] : k;
      if ((ix.slots[i] & ~have) !== 0) continue;
      if (seen && seen[`${cls}:${i}`] !== undefined) continue;
      if (b.textFilter && !b.textFilter(ix.t[i])) continue;
      // a slight preference for lines that say something (very short fragments read oddly without context)
      scored.push({ i, s: scoreTemplate(ix.g[i], shot, line, len, zone, ctl, bk, phIdx, pr, hand) + Math.min(ix.t[i].length, 100) / 100 });
    }
    return scored;
  };
  let scored = take(pool, used);
  if (scored.length < 8) scored = take(undefined, used);
  // Fewer than MIN_UNUSED fresh lines left for this kind of ball (rare class, or the match has used them up): leave it to the
  // built-in lines rather than repeat a corpus line.
  if (scored.length < MIN_UNUSED) return null;
  scored.sort((a, c) => c.s - a.s || a.i - c.i);
  const top = scored.slice(0, Math.min(scored.length, 14));
  const best = top[0].s;
  const pick = sampleWeighted(top, top.map((t) => Math.exp((t.s - best) / 1.6)), rng);
  return {
    text: fill(ix.t[pick.i], b),
    key: `${cls}:${pick.i}`,
    tags: {
      shot: MODEL.dict.shot[shot] ?? null, line: MODEL.dict.line[line] ?? null, length: MODEL.dict.len[len] ?? null,
      zone, control: ctl,
    },
  };
}

/** Stable seed for a ball so commentary never consumes the simulation's RNG stream. */
export function commentarySeed(...parts: (string | number)[]): number {
  return hash32(parts.join("|"));
}
